def weather(api_key, location_name=None, latitude=None, longitude=None, provider=None, timezone=None, request_source=None, idempotency_key=None, units=None, include_raw_payload=None, **_extra):
    import json, os, datetime, time, re, uuid, copy
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0014000" if __import__("os").path.isdir("./environment_mix/0014000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now = datetime.datetime.now(datetime.timezone.utc)

    def _iso(dt):
        if dt is None:
            return None
        if isinstance(dt, str):
            return dt
        if isinstance(dt, datetime.datetime):
            if dt.tzinfo is None:
                dt = dt.replace(tzinfo=datetime.timezone.utc)
            return dt.astimezone(datetime.timezone.utc).isoformat().replace("+00:00", "Z")
        return None

    def _parse_dt(s):
        if s is None:
            return None
        if isinstance(s, datetime.datetime):
            return s if s.tzinfo else s.replace(tzinfo=datetime.timezone.utc)
        if not isinstance(s, str):
            return None
        st = s.strip()
        try:
            if st.endswith("Z"):
                return datetime.datetime.fromisoformat(st[:-1]).replace(tzinfo=datetime.timezone.utc)
            dt = datetime.datetime.fromisoformat(st)
            if dt.tzinfo is None:
                dt = dt.replace(tzinfo=datetime.timezone.utc)
            return dt.astimezone(datetime.timezone.utc)
        except Exception:
            return None

    def _minute_bucket(dt):
        return dt.replace(second=0, microsecond=0)

    def _day_bucket(dt):
        return dt.replace(hour=0, minute=0, second=0, microsecond=0)

    def _new_id(prefix):
        # Examples are ULID-like; use time+uuid for stable uniqueness offline.
        return f"{prefix}{now.strftime('%y%m%d%H%M%S')}_{uuid.uuid4().hex.upper()}"

    def _safe_jsonable(x, _seen=None):
        # Prevent "ValueError: Circular reference detected" by copying only jsonable parts.
        if _seen is None:
            _seen = set()
        oid = id(x)
        if oid in _seen:
            return "<circular>"
        if x is None or isinstance(x, (str, int, float, bool)):
            return x
        if isinstance(x, datetime.datetime):
            return _iso(x)
        if isinstance(x, list):
            _seen.add(oid)
            return [_safe_jsonable(v, _seen) for v in x]
        if isinstance(x, tuple):
            _seen.add(oid)
            return [_safe_jsonable(v, _seen) for v in x]
        if isinstance(x, dict):
            _seen.add(oid)
            out = {}
            for k, v in x.items():
                if isinstance(k, (str, int, float, bool)) or k is None:
                    kk = str(k) if not isinstance(k, str) else k
                else:
                    kk = str(k)
                out[kk] = _safe_jsonable(v, _seen)
            return out
        # fallback
        return str(x)

    # ---------- validate inputs ----------
    if not isinstance(api_key, str) or not re.match(r"^wthr_key_[0-9A-Z]{3,}$", api_key):
        return _err("VALIDATION_ERROR", "api_key must be a string matching ^wthr_key_[0-9A-Z]{3,}$.")
    if location_name is not None and not isinstance(location_name, str):
        return _err("VALIDATION_ERROR", "location_name must be a string when provided.")
    if timezone is not None and not isinstance(timezone, str):
        return _err("VALIDATION_ERROR", "timezone must be a string when provided.")
    if request_source is not None and request_source not in ("mcp", "http", "internal"):
        return _err("VALIDATION_ERROR", "request_source must be one of: mcp, http, internal.")
    if idempotency_key is not None and not isinstance(idempotency_key, str):
        return _err("VALIDATION_ERROR", "idempotency_key must be a string when provided.")
    if units is not None and units not in ("metric", "imperial"):
        return _err("VALIDATION_ERROR", "units must be one of: metric, imperial.")
    if include_raw_payload is not None and not isinstance(include_raw_payload, bool):
        return _err("VALIDATION_ERROR", "include_raw_payload must be a boolean when provided.")
    if provider is not None and provider not in ("open_meteo", "openweathermap", "weatherapi", "mock"):
        return _err("VALIDATION_ERROR", "provider must be one of: open_meteo, openweathermap, weatherapi, mock.")
    if latitude is not None:
        if not isinstance(latitude, (int, float)):
            return _err("VALIDATION_ERROR", "latitude must be a number when provided.")
        if latitude < -90 or latitude > 90:
            return _err("VALIDATION_ERROR", "latitude must be between -90 and 90.")
    if longitude is not None:
        if not isinstance(longitude, (int, float)):
            return _err("VALIDATION_ERROR", "longitude must be a number when provided.")
        if longitude < -180 or longitude > 180:
            return _err("VALIDATION_ERROR", "longitude must be between -180 and 180.")
    if not location_name and (latitude is None or longitude is None):
        return _err("VALIDATION_ERROR", "Provide either location_name or both latitude and longitude.")

    # defaults
    request_source_val = request_source or "mcp"
    include_raw = True if include_raw_payload is True else False

    api_keys = _load("api_keys.json")
    weather_requests = _load("weather_requests.json")
    weather_responses = _load("weather_responses.json")
    provider_configs = _load("provider_configs.json")

    # ---------- authenticate api_key id (explicit credential param) ----------
    key_row = None
    for r in api_keys:
        if isinstance(r, dict) and r.get("id") == api_key:
            key_row = r
            break
    if not key_row or key_row.get("status") != "active":
        # still log the attempt (requests collection is the audit log)
        req_id = _new_id("wthr_req_")
        created = _iso(now)
        finished = _iso(datetime.datetime.now(datetime.timezone.utc))
        weather_requests.append({
            "id": req_id,
            "api_key_id": api_key if key_row else None,
            "tool_name": "weather",
            "status": "failed",
            "request_source": request_source_val,
            "caller_ip": None,
            "user_agent": None,
            "idempotency_key": idempotency_key,
            "started_at": created,
            "finished_at": finished,
            "duration_ms": int(max(0, (time.time() - t0) * 1000)),
            "error_code": "UNAUTHORIZED",
            "error_message": "API key is invalid or not active.",
            "created_at": created,
            "updated_at": finished
        })
        _save("weather_requests.json", weather_requests)
        return _err("UNAUTHORIZED", "API key is invalid, disabled, or revoked.")

    api_key_id = key_row["id"]

    # ---------- idempotency: return existing response without creating new request ----------
    if idempotency_key:
        for req in weather_requests:
            if not isinstance(req, dict):
                continue
            if req.get("api_key_id") == api_key_id and req.get("idempotency_key") == idempotency_key:
                # must return previously stored response (if succeeded)
                rsp = None
                for rr in weather_responses:
                    if isinstance(rr, dict) and rr.get("weather_request_id") == req.get("id"):
                        rsp = rr
                        break
                # If the previous attempt wasn't succeeded or has no response, return a stable replay of status.
                body = {
                    "request": req,
                    "response": rsp if (include_raw and rsp is not None) else (None if rsp is None else {k: v for k, v in rsp.items() if k != "raw_payload"}),
                }
                # Ensure json-serializable (and no circular refs)
                return _safe_jsonable(body)

    # ---------- create request row with status='received' BEFORE any provider selection ----------
    req_id = _new_id("wthr_req_")
    created = _iso(now)
    req_row = {
        "id": req_id,
        "api_key_id": api_key_id,
        "tool_name": "weather",
        "status": "received",
        "request_source": request_source_val,
        "caller_ip": None,
        "user_agent": None,
        "idempotency_key": idempotency_key,
        "started_at": None,
        "finished_at": None,
        "duration_ms": None,
        "error_code": None,
        "error_message": None,
        "created_at": created,
        "updated_at": created,
    }
    weather_requests.append(req_row)
    _save("weather_requests.json", weather_requests)

    def _transition(req, to_status, error_code=None, error_message=None):
        allowed = {
            "received": {"running", "throttled", "failed"},
            "running": {"succeeded", "failed"},
            "succeeded": set(),
            "failed": set(),
            "throttled": set(),
        }
        frm = req.get("status")
        if to_status not in allowed.get(frm, set()):
            return False, _err("INVALID_TRANSITION", f"Invalid status transition {frm} -> {to_status}.")
        req["status"] = to_status
        ts = datetime.datetime.now(datetime.timezone.utc)
        if to_status == "running":
            req["started_at"] = _iso(ts)
        if to_status in ("succeeded", "failed", "throttled"):
            req["finished_at"] = _iso(ts)
            req["duration_ms"] = int(max(0, (time.time() - t0) * 1000))
        if error_code is not None:
            req["error_code"] = error_code
        if error_message is not None:
            req["error_message"] = error_message
        req["updated_at"] = _iso(ts)
        return True, None

    def _persist_req(req):
        for i, r in enumerate(weather_requests):
            if isinstance(r, dict) and r.get("id") == req.get("id"):
                weather_requests[i] = req
                _save("weather_requests.json", weather_requests)
                return True
        return False

    # ---------- rate limit / quota enforcement ----------
    # Enforce only when api_key_id present (it is)
    minute_limit = key_row.get("requests_per_minute_limit")
    day_limit = key_row.get("requests_per_day_limit")
    if not isinstance(minute_limit, int) or not isinstance(day_limit, int) or minute_limit < 0 or day_limit < 0:
        ok, er = _transition(req_row, "failed", "VALIDATION_ERROR", "API key limits are misconfigured.")
        _persist_req(req_row)
        return er if er else _err("VALIDATION_ERROR", "API key limits are misconfigured.")

    # Compute buckets, reset counters if boundary changed
    now_min = _minute_bucket(now)
    now_day = _day_bucket(now)
    prev_min = _parse_dt(key_row.get("usage_minute"))
    prev_day = _parse_dt(key_row.get("usage_day"))

    if prev_min is None or _minute_bucket(prev_min) != now_min:
        key_row["usage_minute"] = _iso(now_min)
        key_row["usage_minute_count"] = 0
    if prev_day is None or _day_bucket(prev_day) != now_day:
        key_row["usage_day"] = _iso(now_day)
        key_row["usage_day_count"] = 0

    if key_row.get("usage_minute_count", 0) >= minute_limit or key_row.get("usage_day_count", 0) >= day_limit:
        ok, er = _transition(req_row, "throttled", "RATE_LIMIT", "Rate limit or daily quota exceeded.")
        _persist_req(req_row)
        # persist key boundary resets even on throttling
        key_row["updated_at"] = _iso(datetime.datetime.now(datetime.timezone.utc))
        for i, r in enumerate(api_keys):
            if isinstance(r, dict) and r.get("id") == api_key_id:
                api_keys[i] = key_row
                _save("api_keys.json", api_keys)
                break
        return _err("RATE_LIMIT", "Rate limit or daily quota exceeded.")

    # increment usage (this request counts even if it later fails)
    key_row["usage_minute_count"] = int(key_row.get("usage_minute_count", 0)) + 1
    key_row["usage_day_count"] = int(key_row.get("usage_day_count", 0)) + 1
    key_row["last_used_at"] = _iso(datetime.datetime.now(datetime.timezone.utc))
    key_row["updated_at"] = _iso(datetime.datetime.now(datetime.timezone.utc))
    for i, r in enumerate(api_keys):
        if isinstance(r, dict) and r.get("id") == api_key_id:
            api_keys[i] = key_row
            _save("api_keys.json", api_keys)
            break

    # ---------- provider selection ----------
    active_cfgs = [c for c in provider_configs if isinstance(c, dict) and c.get("status") == "active"]
    if provider:
        active_cfgs = [c for c in active_cfgs if c.get("provider") == provider]
    # lowest priority integer wins
    def _prio(c):
        p = c.get("priority")
        return p if isinstance(p, int) else 10**9
    active_cfgs.sort(key=_prio)
    cfg = active_cfgs[0] if active_cfgs else None

    if not cfg:
        ok, er = _transition(req_row, "failed", "NO_PROVIDER_AVAILABLE", "No active provider configuration available.")
        _persist_req(req_row)
        return _err("CONFLICT", "No active provider configuration available.", rule="Provider selection requires an active provider_configs row.", error_code="NO_PROVIDER_AVAILABLE")

    # transition to running
    ok, er = _transition(req_row, "running")
    if not ok:
        _persist_req(req_row)
        return er
    _persist_req(req_row)

    # ---------- fulfill (offline): choose from existing stored response patterns or synthesize deterministic payload ----------
    # Real backend would call upstream; here we produce a payload and persist it as returned to client.
    # To avoid fabricating rows not in store? Business rules require creating a response row for succeeded.
    # We'll create exactly one response row for this new request, derived deterministically from input.
    resolved_lat = latitude
    resolved_lon = longitude
    if resolved_lat is None or resolved_lon is None:
        # minimal deterministic "geocode"
        h = abs(hash((location_name or "").strip().lower())) % 1000000
        resolved_lat = (h % 18000) / 100.0 - 90.0
        resolved_lon = ((h // 18000) % 36000) / 100.0 - 180.0

    provider_name = cfg.get("provider") if cfg.get("provider") in ("open_meteo", "openweathermap", "weatherapi", "mock") else "unknown"
    obs_time = datetime.datetime.now(datetime.timezone.utc).replace(microsecond=0)

    # deterministic values
    base = (abs(hash((resolved_lat, resolved_lon, obs_time.isoformat()[:13]))) % 2500) / 100.0  # 0..25
    temp_c = (base * 1.2) + 5.0
    humidity = int(abs(hash(("h", resolved_lat, resolved_lon))) % 101)
    wind = (abs(hash(("w", resolved_lat, resolved_lon))) % 1500) / 100.0

    if units == "imperial":
        temperature = temp_c * 9.0 / 5.0 + 32.0
        wind_speed = wind * 2.2369362920544  # m/s to mph
        temp_field = {"temperature_f": round(temperature, 2)}
        wind_field = {"wind_speed_mph": round(wind_speed, 2)}
    else:
        temp_field = {"temperature_c": round(temp_c, 2)}
        wind_field = {"wind_speed_mps": round(wind, 2)}

    payload = {
        "provider": provider_name,
        "location": {
            "name": location_name,
            "latitude": resolved_lat,
            "longitude": resolved_lon,
            "timezone": timezone
        },
        "observed_at": _iso(obs_time),
        "current": {
            **temp_field,
            "humidity_pct": humidity,
            **wind_field,
            "condition": {"code": "unknown", "text": "Unknown"}
        }
    }

    # Persist response row
    rsp_id = _new_id("wthr_rsp_")
    rsp_row = {
        "id": rsp_id,
        "weather_request_id": req_id,
        "provider": provider_name if provider_name in ("open_meteo", "openweathermap", "weatherapi", "mock") else "unknown",
        "provider_request_id": None,
        "location_name": location_name,
        "latitude": float(resolved_lat) if resolved_lat is not None else None,
        "longitude": float(resolved_lon) if resolved_lon is not None else None,
        "timezone": timezone,
        "observed_at": _iso(obs_time),
        "temperature_c": round(temp_c, 2) if units != "imperial" else None,
        "humidity_pct": humidity,
        "wind_speed_mps": round(wind, 2) if units != "imperial" else None,
        "condition_code": "unknown",
        "condition_text": "Unknown",
        "raw_payload": _safe_jsonable(payload),
        "created_at": _iso(datetime.datetime.now(datetime.timezone.utc)),
        "updated_at": _iso(datetime.datetime.now(datetime.timezone.utc)),
    }

    # enforce unique(weather_request_id)
    for existing in weather_responses:
        if isinstance(existing, dict) and existing.get("weather_request_id") == req_id:
            ok, er = _transition(req_row, "failed", "CONFLICT", "A response already exists for this request.")
            _persist_req(req_row)
            return _err("CONFLICT", "A response already exists for this request.")

    weather_responses.append(rsp_row)
    _save("weather_responses.json", weather_responses)

    ok, er = _transition(req_row, "succeeded")
    _persist_req(req_row)

    result_response = rsp_row if include_raw else {k: v for k, v in rsp_row.items() if k != "raw_payload"}
    return _safe_jsonable({
        "request": req_row,
        "response": result_response
    })

def me(api_key, **_extra):
    import json, os, datetime, time, re
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0014000" if __import__("os").path.isdir("./environment_mix/0014000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    def _now_utc():
        return datetime.datetime.now(datetime.timezone.utc)
    def _iso(dt):
        if dt is None:
            return None
        if isinstance(dt, str):
            return dt
        return dt.astimezone(datetime.timezone.utc).isoformat().replace("+00:00", "Z")

    # Validate api_key format
    if not isinstance(api_key, str) or not re.match(r"^wthr_key_[0-9A-Z]{3,}$", api_key):
        return _err("VALIDATION_ERROR", "Invalid api_key format.")

    api_keys = _load("api_keys.json")
    weather_requests = _load("weather_requests.json")

    key_row = None
    for k in api_keys:
        if k.get("id") == api_key:
            key_row = k
            break

    # Log call as a weather_requests row? tool_name enum only 'weather', so cannot. No other log collection exists.
    # We still update usage counters only on successful authenticated use for this identity endpoint? Spec doesn't say.
    # We'll avoid mutating quotas here, but we will update last_used_at on success as "authenticated use".
    if key_row is None:
        return _err("UNAUTHORIZED", "API key not found.")

    if key_row.get("status") != "active":
        return _err("UNAUTHORIZED", f"API key is {key_row.get('status')}.")

    now = _now_utc()
    key_row["last_used_at"] = _iso(now)
    key_row["updated_at"] = _iso(now)
    _save("api_keys.json", api_keys)

    return {
        "id": key_row.get("id"),
        "label": key_row.get("label"),
        "owner_type": key_row.get("owner_type"),
        "owner_id": key_row.get("owner_id"),
        "status": key_row.get("status"),
        "requests_per_minute_limit": key_row.get("requests_per_minute_limit"),
        "requests_per_day_limit": key_row.get("requests_per_day_limit"),
        "usage_minute": key_row.get("usage_minute"),
        "usage_minute_count": key_row.get("usage_minute_count"),
        "usage_day": key_row.get("usage_day"),
        "usage_day_count": key_row.get("usage_day_count"),
        "last_used_at": key_row.get("last_used_at"),
        "created_at": key_row.get("created_at"),
        "updated_at": key_row.get("updated_at"),
        "latency_ms": max(0, int((time.time() - t0) * 1000))
    }

def api_keys_list(api_key, status=None, owner_type=None, owner_id=None, limit=None, cursor=None, **_extra):
    import json, os, datetime, time, re, base64
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0014000" if __import__("os").path.isdir("./environment_mix/0014000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    def _now_utc():
        return datetime.datetime.now(datetime.timezone.utc)
    def _iso(dt):
        if dt is None:
            return None
        if isinstance(dt, str):
            return dt
        return dt.astimezone(datetime.timezone.utc).isoformat().replace("+00:00", "Z")

    if not isinstance(api_key, str) or not re.match(r"^wthr_key_[0-9A-Z]{3,}$", api_key):
        return _err("VALIDATION_ERROR", "Invalid api_key format.")

    if status is not None and status not in ("active", "disabled", "revoked"):
        return _err("VALIDATION_ERROR", "Invalid status filter.")
    if owner_type is not None and owner_type not in ("user", "service"):
        return _err("VALIDATION_ERROR", "Invalid owner_type filter.")
    if owner_id is not None and not isinstance(owner_id, str):
        return _err("VALIDATION_ERROR", "owner_id must be a string.")
    if limit is not None:
        if not isinstance(limit, int):
            return _err("VALIDATION_ERROR", "limit must be an integer.")
        if limit < 1 or limit > 200:
            return _err("VALIDATION_ERROR", "limit out of range.")
    else:
        limit = 50
    if cursor is not None and not isinstance(cursor, str):
        return _err("VALIDATION_ERROR", "cursor must be a string.")

    api_keys = _load("api_keys.json")

    caller = None
    for k in api_keys:
        if k.get("id") == api_key:
            caller = k
            break
    if caller is None or caller.get("status") != "active":
        return _err("UNAUTHORIZED", "API key invalid, disabled, or revoked.")

    # Visibility: keys visible to caller are those with same owner_type+owner_id, plus caller itself.
    vis_owner_type = caller.get("owner_type")
    vis_owner_id = caller.get("owner_id")

    rows = []
    for k in api_keys:
        if k.get("id") == caller.get("id") or (k.get("owner_type") == vis_owner_type and k.get("owner_id") == vis_owner_id):
            rows.append(k)

    # Apply filters
    if status is not None:
        rows = [r for r in rows if r.get("status") == status]
    if owner_type is not None:
        rows = [r for r in rows if r.get("owner_type") == owner_type]
    if owner_id is not None:
        rows = [r for r in rows if r.get("owner_id") == owner_id]

    # Sort by created_at desc, then id
    def _sort_key(r):
        ca = r.get("created_at") or ""
        return (ca, r.get("id") or "")
    rows.sort(key=_sort_key, reverse=True)

    # Cursor: opaque base64 of last id
    start = 0
    if cursor:
        try:
            decoded = base64.urlsafe_b64decode(cursor.encode("utf-8")).decode("utf-8")
            # decoded is last_seen_id
            for i, r in enumerate(rows):
                if r.get("id") == decoded:
                    start = i + 1
                    break
        except Exception:
            return _err("VALIDATION_ERROR", "Invalid cursor.")

    page = rows[start:start + limit]
    has_more = start + limit < len(rows)
    next_cursor = None
    if has_more and page:
        last_id = page[-1].get("id")
        next_cursor = base64.urlsafe_b64encode(last_id.encode("utf-8")).decode("utf-8")

    # Never return raw key material (key_hash is stored; return prefix and metadata only)
    def _public(k):
        return {
            "id": k.get("id"),
            "key_prefix": k.get("key_prefix"),
            "label": k.get("label"),
            "owner_type": k.get("owner_type"),
            "owner_id": k.get("owner_id"),
            "status": k.get("status"),
            "requests_per_minute_limit": k.get("requests_per_minute_limit"),
            "requests_per_day_limit": k.get("requests_per_day_limit"),
            "usage_minute": k.get("usage_minute"),
