        "latency_ms": max(0, int((time.time() - t0) * 1000))
    }

def api_keys_create(api_key, label, owner_type, owner_id, requests_per_minute_limit=None, requests_per_day_limit=None, **_extra):
    import json, os, datetime, time, re, secrets, hashlib
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0014000" if __import__("os").path.isdir("./environment_mix/0014000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    def _now_utc():
        return datetime.datetime.now(datetime.timezone.utc)
    def _iso(dt):
        if dt is None:
            return None
        if isinstance(dt, str):
            return dt
        return dt.astimezone(datetime.timezone.utc).isoformat().replace("+00:00", "Z")

    # Validate caller api_key id format and authenticate
    if not isinstance(api_key, str) or not re.match(r"^wthr_key_[0-9A-Z]{3,}$", api_key):
        return _err("VALIDATION_ERROR", "Invalid api_key format.")
    if not isinstance(label, str) or not (1 <= len(label) <= 120):
        return _err("VALIDATION_ERROR", "label must be 1-120 characters.")
    if owner_type not in ("user", "service"):
        return _err("VALIDATION_ERROR", "owner_type must be 'user' or 'service'.")
    if not isinstance(owner_id, str) or not (1 <= len(owner_id) <= 200):
        return _err("VALIDATION_ERROR", "owner_id must be 1-200 characters.")

    if requests_per_minute_limit is None:
        requests_per_minute_limit = 60
    if requests_per_day_limit is None:
        requests_per_day_limit = 10000

    if not isinstance(requests_per_minute_limit, int) or not (1 <= requests_per_minute_limit <= 100000):
        return _err("VALIDATION_ERROR", "requests_per_minute_limit out of range.")
    if not isinstance(requests_per_day_limit, int) or not (1 <= requests_per_day_limit <= 10000000):
        return _err("VALIDATION_ERROR", "requests_per_day_limit out of range.")

    api_keys = _load("api_keys.json")
    caller = None
    for k in api_keys:
        if k.get("id") == api_key:
            caller = k
            break
    if caller is None or caller.get("status") != "active":
        return _err("UNAUTHORIZED", "API key invalid, disabled, or revoked.")

    # Authorization: allow creating keys only for same owner as caller (or if caller is service key, allow any)
    if caller.get("owner_type") != "service":
        if owner_type != caller.get("owner_type") or owner_id != caller.get("owner_id"):
            return _err("UNAUTHORIZED", "Not permitted to create keys for a different owner.")

    # Generate raw key ONCE, store only hash + prefix; id is also client-visible id.
    raw = "wthr_key_" + secrets.token_hex(16).upper()
    key_id = raw  # tool patterns treat api_key as api_keys.id

    key_prefix = raw[:10]
    key_hash = hashlib.sha256(raw.encode("utf-8")).hexdigest()

    # Enforce unique(key_hash) and unique(key_prefix) and unique(id)
    for k in api_keys:
        if k.get("id") == key_id:
            return _err("CONFLICT", "Generated key id collided; retry.")
        if k.get("key_hash") == key_hash:
            return _err("CONFLICT", "Generated key hash collided; retry.")
        if k.get("key_prefix") == key_prefix:
            return _err("CONFLICT", "Generated key prefix collided; retry.")

    now = _now_utc()
    row = {
        "id": key_id,
        "key_hash": key_hash,
        "key_prefix": key_prefix,
        "label": label,
        "owner_type": owner_type,
        "owner_id": owner_id,
        "status": "active",
        "requests_per_minute_limit": int(requests_per_minute_limit),
        "requests_per_day_limit": int(requests_per_day_limit),
        "usage_day": None,
        "usage_day_count": 0,
        "usage_minute": None,
        "usage_minute_count": 0,
        "last_used_at": None,
        "created_at": _iso(now),
        "updated_at": _iso(now),
    }

    api_keys.append(row)
    # Update caller last_used_at
    caller["last_used_at"] = _iso(now)
    caller["updated_at"] = _iso(now)
    _save("api_keys.json", api_keys)

    # Return raw key once, plus metadata (never return key_hash)
    return {
        "api_key": raw,
        "key": {
            "id": row.get("id"),
            "key_prefix": row.get("key_prefix"),
            "label": row.get("label"),
            "owner_type": row.get("owner_type"),
            "owner_id": row.get("owner_id"),
            "status": row.get("status"),
            "requests_per_minute_limit": row.get("requests_per_minute_limit"),
            "requests_per_day_limit": row.get("requests_per_day_limit"),
            "created_at": row.get("created_at"),
            "updated_at": row.get("updated_at"),
        },
        "latency_ms": max(0, int((time.time() - t0) * 1000))
    }

def api_keys_update(api_key, id, label=None, status=None, requests_per_minute_limit=None, requests_per_day_limit=None, **_extra):
    import json, os, datetime, time, re
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0014000" if __import__("os").path.isdir("./environment_mix/0014000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now = datetime.datetime.now(datetime.timezone.utc)

    def _iso(dt):
        if dt is None:
            return None
        if isinstance(dt, str):
            return dt
        if isinstance(dt, datetime.datetime):
            if dt.tzinfo is None:
                dt = dt.replace(tzinfo=datetime.timezone.utc)
            return dt.astimezone(datetime.timezone.utc).isoformat().replace("+00:00", "Z")
        return None

    def _new_req_id():
        return "wthr_req_" + now.strftime("%y%m%d%H%M%S") + "_" + os.urandom(6).hex().upper()

    # Validate inputs
    if not isinstance(api_key, str) or not re.match(r"^wthr_key_[0-9A-Z]{3,}$", api_key):
        return _err("VALIDATION_ERROR", "api_key must be a string matching ^wthr_key_[0-9A-Z]{3,}$.")
    if not isinstance(id, str) or not re.match(r"^wthr_key_[0-9A-Z]{3,}$", id):
        return _err("VALIDATION_ERROR", "id must be a string matching ^wthr_key_[0-9A-Z]{3,}$.")
    if label is not None:
        if not isinstance(label, str):
            return _err("VALIDATION_ERROR", "label must be a string.")
        if len(label) < 1 or len(label) > 120:
            return _err("VALIDATION_ERROR", "label length must be between 1 and 120.")
    if status is not None and status not in ("active", "disabled", "revoked"):
        return _err("VALIDATION_ERROR", "status must be one of: active, disabled, revoked.")
    if requests_per_minute_limit is not None:
        if not isinstance(requests_per_minute_limit, int):
            return _err("VALIDATION_ERROR", "requests_per_minute_limit must be an integer.")
        if requests_per_minute_limit < 1 or requests_per_minute_limit > 100000:
            return _err("VALIDATION_ERROR", "requests_per_minute_limit must be between 1 and 100000.")
    if requests_per_day_limit is not None:
        if not isinstance(requests_per_day_limit, int):
            return _err("VALIDATION_ERROR", "requests_per_day_limit must be an integer.")
        if requests_per_day_limit < 1 or requests_per_day_limit > 10000000:
            return _err("VALIDATION_ERROR", "requests_per_day_limit must be between 1 and 10000000.")

    api_keys = _load("api_keys.json")
    weather_requests = _load("weather_requests.json")

    # Authenticate caller api_key (must be active)
    caller = None
    for r in api_keys:
        if isinstance(r, dict) and r.get("id") == api_key:
            caller = r
            break
    if not caller or caller.get("status") != "active":
        # log failed auth
        finished = datetime.datetime.now(datetime.timezone.utc)
        dur = int(max(0, (time.time() - t0) * 1000))
        weather_requests.append({
            "id": _new_req_id(),
            "api_key_id": api_key if caller else None,
            "tool_name": "weather",
            "status": "failed",
            "request_source": "internal",
            "caller_ip": None,
            "user_agent": None,
            "idempotency_key": None,
            "started_at": _iso(now),
            "finished_at": _iso(finished),
            "duration_ms": dur,
            "error_code": "UNAUTHORIZED",
            "error_message": "API key is invalid or not active.",
            "created_at": _iso(now),
            "updated_at": _iso(finished),
        })
        _save("weather_requests.json", weather_requests)
        return _err("UNAUTHORIZED", "API key is invalid, disabled, or revoked.")

    # Find target key
    idx = None
    target = None
    for i, r in enumerate(api_keys):
        if isinstance(r, dict) and r.get("id") == id:
            idx = i
            target = r
            break
    if target is None:
        # log NOT_FOUND
        finished = datetime.datetime.now(datetime.timezone.utc)
        dur = int(max(0, (time.time() - t0) * 1000))
        weather_requests.append({
            "id": _new_req_id(),
            "api_key_id": caller.get("id"),
            "tool_name": "weather",
            "status": "failed",
            "request_source": "internal",
            "caller_ip": None,
            "user_agent": None,
            "idempotency_key": None,
            "started_at": _iso(now),
            "finished_at": _iso(finished),
            "duration_ms": dur,
            "error_code": "NOT_FOUND",
            "error_message": "API key id not found.",
            "created_at": _iso(now),
            "updated_at": _iso(finished),
        })
        _save("weather_requests.json", weather_requests)
        return _err("NOT_FOUND", "API key not found.")

    # Apply changes (NO SUCCESS WITHOUT EFFECT: if row exists, accept even if no-op by returning the row;
    # the audit defect expects not rejecting as NOT_FOUND for no-op.)
    changed = False

    if label is not None and label != target.get("label"):
        target["label"] = label
        changed = True

    if requests_per_minute_limit is not None and requests_per_minute_limit != target.get("requests_per_minute_limit"):
        target["requests_per_minute_limit"] = requests_per_minute_limit
        changed = True

    if requests_per_day_limit is not None and requests_per_day_limit != target.get("requests_per_day_limit"):
        target["requests_per_day_limit"] = requests_per_day_limit
        changed = True

    if status is not None and status != target.get("status"):
        allowed = {
            "active": {"disabled", "revoked"},
            "disabled": {"active", "revoked"},
            "revoked": set(),
        }
        cur = target.get("status")
        if status not in allowed.get(cur, set()):
            finished = datetime.datetime.now(datetime.timezone.utc)
            dur = int(max(0, (time.time() - t0) * 1000))
            weather_requests.append({
                "id": _new_req_id(),
                "api_key_id": caller.get("id"),
                "tool_name": "weather",
                "status": "failed",
                "request_source": "internal",
                "caller_ip": None,
                "user_agent": None,
                "idempotency_key": None,
                "started_at": _iso(now),
                "finished_at": _iso(finished),
                "duration_ms": dur,
                "error_code": "INVALID_TRANSITION",
                "error_message": f"Invalid API key status transition {cur} -> {status}.",
                "created_at": _iso(now),
                "updated_at": _iso(finished),
            })
            _save("weather_requests.json", weather_requests)
            return _err("INVALID_TRANSITION", f"Invalid API key status transition {cur} -> {status}.")
        target["status"] = status
        changed = True

    # Always update updated_at when mutation endpoint called and target exists
    target["updated_at"] = _iso(datetime.datetime.now(datetime.timezone.utc))
    if "created_at" not in target or not target.get("created_at"):
        target["created_at"] = _iso(now)

    api_keys[idx] = target
    _save("api_keys.json", api_keys)

    # Log call in weather_requests as audit dynamics
    finished = datetime.datetime.now(datetime.timezone.utc)
    dur = int(max(0, (time.time() - t0) * 1000))
    weather_requests.append({
        "id": _new_req_id(),
        "api_key_id": caller.get("id"),
        "tool_name": "weather",
        "status": "succeeded",
        "request_source": "internal",
        "caller_ip": None,
        "user_agent": None,
        "idempotency_key": None,
        "started_at": _iso(now),
        "finished_at": _iso(finished),
        "duration_ms": dur,
        "error_code": None,
        "error_message": None,
        "created_at": _iso(now),
        "updated_at": _iso(finished),
    })
    _save("weather_requests.json", weather_requests)

    return {
        "api_key": target,
        "changed": bool(changed)
    }

def weather_requests_list(api_key, api_key_id=None, status=None, idempotency_key=None, created_after=None, created_before=None, limit=None, cursor=None, **_extra):
    import json, os, datetime, time, re, base64

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0014000" if __import__("os").path.isdir("./environment_mix/0014000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now = datetime.datetime.now(datetime.timezone.utc)

    def _iso(dt):
        if dt is None:
            return None
        if isinstance(dt, str):
            return dt
        if isinstance(dt, datetime.datetime):
            if dt.tzinfo is None:
                dt = dt.replace(tzinfo=datetime.timezone.utc)
            return dt.isoformat().replace("+00:00", "Z")
        return None

    def _parse_rfc3339(s):
        if s is None:
            return None
        if not isinstance(s, str):
            return None
        try:
            if s.endswith("Z"):
                return datetime.datetime.fromisoformat(s[:-1]).replace(tzinfo=datetime.timezone.utc)
            dt = datetime.datetime.fromisoformat(s)
            if dt.tzinfo is None:
                dt = dt.replace(tzinfo=datetime.timezone.utc)
            return dt.astimezone(datetime.timezone.utc)
        except Exception:
            return None

    def _new_req_id():
        return "wthr_req_" + now.strftime("%Y%m%d%H%M%S") + "_" + os.urandom(3).hex()

    def _log(weather_requests, api_key_id_used, st, error_code=None, error_message=None):
        rid = _new_req_id()
        weather_requests.append({
            "id": rid,
            "api_key_id": api_key_id_used,
            "tool_name": "weather",
            "status": st,
            "request_source": "internal",
            "caller_ip": None,
            "user_agent": None,
            "idempotency_key": None,
            "started_at": None,
            "finished_at": _iso(now),
            "duration_ms": max(0, int((time.time() - t0) * 1000)),
            "error_code": error_code,
            "error_message": error_message,
            "created_at": _iso(now),
            "updated_at": _iso(now),
        })
        return rid

    # Validate inputs
    pat = re.compile(r"^wthr_key_[0-9A-Z]{3,}$")
    if not isinstance(api_key, str) or not pat.match(api_key):
        wr = _load("weather_requests.json")
        _log(wr, None, "failed", "VALIDATION_ERROR", "Invalid api_key format.")
        _save("weather_requests.json", wr)
        return _err("VALIDATION_ERROR", "Invalid api_key format.", field="api_key")

    if api_key_id is not None:
        if not isinstance(api_key_id, str) or not pat.match(api_key_id):
            wr = _load("weather_requests.json")
            _log(wr, api_key, "failed", "VALIDATION_ERROR", "Invalid api_key_id format.")
            _save("weather_requests.json", wr)
            return _err("VALIDATION_ERROR", "Invalid api_key_id format.", field="api_key_id")

    if status is not None:
        if not isinstance(status, str) or status not in ("received", "running", "succeeded", "failed", "throttled"):
            wr = _load("weather_requests.json")
            _log(wr, api_key, "failed", "VALIDATION_ERROR", "Invalid status filter.")
            _save("weather_requests.json", wr)
            return _err("VALIDATION_ERROR", "Invalid status.", field="status")

    if idempotency_key is not None and not isinstance(idempotency_key, str):
        wr = _load("weather_requests.json")
        _log(wr, api_key, "failed", "VALIDATION_ERROR", "idempotency_key must be string.")
        _save("weather_requests.json", wr)
        return _err("VALIDATION_ERROR", "idempotency_key must be a string.", field="idempotency_key")

    ca = _parse_rfc3339(created_after) if created_after is not None else None
    if created_after is not None and ca is None:
        wr = _load("weather_requests.json")
        _log(wr, api_key, "failed", "VALIDATION_ERROR", "created_after must be RFC3339 date-time.")
        _save("weather_requests.json", wr)
        return _err("VALIDATION_ERROR", "created_after must be RFC3339 date-time.", field="created_after")

    cb = _parse_rfc3339(created_before) if created_before is not None else None
    if created_before is not None and cb is None:
        wr = _load("weather_requests.json")
        _log(wr, api_key, "failed", "VALIDATION_ERROR", "created_before must be RFC3339 date-time.")
        _save("weather_requests.json", wr)
        return _err("VALIDATION_ERROR", "created_before must be RFC3339 date-time.", field="created_before")

    if limit is None:
        limit = 50
    if not isinstance(limit, int):
        wr = _load("weather_requests.json")
        _log(wr, api_key, "failed", "VALIDATION_ERROR", "limit must be integer.")
        _save("weather_requests.json", wr)
        return _err("VALIDATION_ERROR", "limit must be an integer.", field="limit")
    if not (1 <= limit <= 200):
        wr = _load("weather_requests.json")
        _log(wr, api_key, "failed", "VALIDATION_ERROR", "limit out of range.")
        _save("weather_requests.json", wr)
        return _err("VALIDATION_ERROR", "limit must be 1..200.", field="limit")

    # Load store
    api_keys = _load("api_keys.json")
    weather_requests = _load("weather_requests.json")

    # Authenticate caller key
    caller = next((r for r in api_keys if r.get("id") == api_key), None)
    if caller is None:
        _log(weather_requests, None, "failed", "UNAUTHORIZED", "Invalid api_key.")
        _save("weather_requests.json", weather_requests)
        return _err("UNAUTHORIZED", "Invalid api_key.")
    if caller.get("status") != "active":
        _log(weather_requests, caller.get("id"), "failed", "UNAUTHORIZED", "API key is not active.")
        _save("weather_requests.json", weather_requests)
        return _err("UNAUTHORIZED", "API key is disabled or revoked.")

    # Decode cursor: base64url(json {"after_created_at": "...", "after_id":"..."})
    after_created_at = None
    after_id = None
    if cursor is not None:
        if not isinstance(cursor, str) or cursor == "":
            _log(weather_requests, caller.get("id"), "failed", "VALIDATION_ERROR", "Invalid cursor.")
            _save("weather_requests.json", weather_requests)
            return _err("VALIDATION_ERROR", "Invalid cursor.", field="cursor")
        try:
            pad = "=" * (-len(cursor) % 4)
            raw = base64.urlsafe_b64decode((cursor + pad).encode("utf-8")).decode("utf-8")
            obj = json.loads(raw)
            after_created_at = _parse_rfc3339(obj.get("after_created_at")) if isinstance(obj, dict) else None
            after_id = obj.get("after_id") if isinstance(obj, dict) else None
            if obj is None or after_created_at is None or not isinstance(after_id, str):
                raise ValueError("bad cursor")
        except Exception:
            _log(weather_requests, caller.get("id"), "failed", "VALIDATION_ERROR", "Cursor could not be decoded.")
            _save("weather_requests.json", weather_requests)
            return _err("VALIDATION_ERROR", "Cursor is invalid or expired.", field="cursor")

    def _created_dt(row):
        dt = _parse_rfc3339(row.get("created_at"))
        return dt

    # Filter
    rows = [r for r in weather_requests if r.get("tool_name") == "weather"]

    if api_key_id is not None:
        rows = [r for r in rows if r.get("api_key_id") == api_key_id]
    if status is not None:
        rows = [r for r in rows if r.get("status") == status]
    if idempotency_key is not None:
        rows = [r for r in rows if r.get("idempotency_key") == idempotency_key]
    if ca is not None:
        rows = [r for r in rows if (_created_dt(r) is not None and _created_dt(r) >= ca)]
    if cb is not None:
        rows = [r for r in rows if (_created_dt(r) is not None and _created_dt(r) < cb)]

    # Sort newest first (created_at desc, id desc)
    def _sort_key(r):
        dt = _created_dt(r)
        if dt is None:
            dt = datetime.datetime(1970, 1, 1, tzinfo=datetime.timezone.utc)
        return (dt, str(r.get("id") or ""))
    rows.sort(key=_sort_key, reverse=True)

    # Apply cursor (exclusive): return items with (created_at,id) < (after_created_at,after_id) in this desc order
    if after_created_at is not None and after_id is not None:
        filtered = []
        for r in rows:
            dt = _created_dt(r)
            if dt is None:
                continue
            rid = str(r.get("id") or "")
            # in descending order, "after" points to last item seen; we want strictly older/smaller
            if (dt < after_created_at) or (dt == after_created_at and rid < after_id):
                filtered.append(r)
        rows = filtered

    total = len(rows)
    page = rows[:limit]
    has_more = total > len(page)

    next_cursor = None
    if has_more and page:
        last = page[-1]
        last_dt = _created_dt(last)
        if last_dt is None:
            last_dt = now
        payload = {"after_created_at": _iso(last_dt), "after_id": str(last.get("id") or "")}
        enc = base64.urlsafe_b64encode(json.dumps(payload, separators=(",", ":")).encode("utf-8")).decode("utf-8").rstrip("=")
        next_cursor = enc

    # Log this list call as a request row (audit dynamics)
    _log(weather_requests, caller.get("id"), "succeeded", None, None)
    _save("weather_requests.json", weather_requests)

    return {
        "data": page,
        "meta": {
            "total": total,
            "limit": limit,
            "has_more": has_more,
            "next_cursor": next_cursor,
            "duration_ms": max(0, int((time.time() - t0) * 1000)),
        },
    }

def provider_configs_update(api_key, id, status=None, base_url=None, auth_type=None, api_key_ref=None, priority=None, timeout_ms=None, max_retries=None, **_extra):
    import json, os, datetime, re, time

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0014000" if __import__("os").path.isdir("./environment_mix/0014000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    def _now():
        return datetime.datetime.now(datetime.timezone.utc)

    def _iso(dt):
        if dt is None:
            return None
        if isinstance(dt, str):
            return dt
        if isinstance(dt, datetime.datetime):
            if dt.tzinfo is None:
                dt = dt.replace(tzinfo=datetime.timezone.utc)
            return dt.astimezone(datetime.timezone.utc).isoformat().replace("+00:00", "Z")
        return None

    def _parse_iso(s):
        if s is None:
            return None
        if isinstance(s, datetime.datetime):
            return s if s.tzinfo else s.replace(tzinfo=datetime.timezone.utc)
        if not isinstance(s, str) or not s:
            return None
        try:
            if s.endswith("Z"):
                return datetime.datetime.fromisoformat(s.replace("Z", "+00:00"))
            return datetime.datetime.fromisoformat(s)
        except ValueError:
            return None

    def _truncate_day(dt):
        dt = dt.astimezone(datetime.timezone.utc)
        return dt.replace(hour=0, minute=0, second=0, microsecond=0)

    def _truncate_minute(dt):
        dt = dt.astimezone(datetime.timezone.utc)
        return dt.replace(second=0, microsecond=0)

    def _gen_id(prefix):
        # time-sortable-ish id similar to existing dataset, no external deps
        dt = _now()
        ms = int(dt.timestamp() * 1000)
        rnd = os.urandom(10).hex().upper()
        return f"{prefix}_{ms:013d}{rnd}"

    def _append_weather_request_log(api_key_id, status_val, started_at, finished_at, err_code=None, err_msg=None):
        reqs = _load("weather_requests.json")
        if not isinstance(reqs, list):
            reqs = []
        duration_ms = None
        if started_at and finished_at:
            duration_ms = int(max(0, (finished_at - started_at).total_seconds() * 1000))
        row = {
            "id": _gen_id("wthr_req"),
            "api_key_id": api_key_id,
            "tool_name": "weather",
            "status": status_val,
            "request_source": "internal",
            "caller_ip": None,
            "user_agent": None,
            "idempotency_key": None,
            "started_at": _iso(started_at),
            "finished_at": _iso(finished_at),
            "duration_ms": duration_ms,
            "error_code": err_code,
            "error_message": err_msg,
            "created_at": _iso(started_at or _now()),
            "updated_at": _iso(finished_at or _now()),
        }
        reqs.append(row)
        _save("weather_requests.json", reqs)
        return row

    def _resolve_key_and_enforce_limits(api_key_id, started_at):
        keys = _load("api_keys.json")
        if not isinstance(keys, list):
            keys = []

        key_row = None
        for k in keys:
            if isinstance(k, dict) and k.get("id") == api_key_id:
                key_row = k
                break
        if not key_row:
            return None, _err("UNAUTHORIZED", "Invalid api_key: no such key id.")

        if key_row.get("status") != "active":
            return None, _err("UNAUTHORIZED", "API key is not active.", status=key_row.get("status"))

        # Enforce minute/day counters. If exceeded: must record throttled request and stop.
        now = started_at
        minute_bucket = _truncate_minute(now)
        day_bucket = _truncate_day(now)

        usage_minute = _parse_iso(key_row.get("usage_minute"))
        usage_day = _parse_iso(key_row.get("usage_day"))

        if usage_minute is None or usage_minute != minute_bucket:
            key_row["usage_minute"] = _iso(minute_bucket)
            key_row["usage_minute_count"] = 0
        if usage_day is None or usage_day != day_bucket:
            key_row["usage_day"] = _iso(day_bucket)
            key_row["usage_day_count"] = 0

        rpm_limit = key_row.get("requests_per_minute_limit")
        rpd_limit = key_row.get("requests_per_day_limit")
        if not isinstance(rpm_limit, int) or rpm_limit < 0:
            return None, _err("VALIDATION_ERROR", "API key has invalid requests_per_minute_limit.")
        if not isinstance(rpd_limit, int) or rpd_limit < 0:
            return None, _err("VALIDATION_ERROR", "API key has invalid requests_per_day_limit.")

        minute_count = key_row.get("usage_minute_count", 0)
        day_count = key_row.get("usage_day_count", 0)
        if not isinstance(minute_count, int) or minute_count < 0:
            minute_count = 0
        if not isinstance(day_count, int) or day_count < 0:
            day_count = 0

        # Throttle if next request would exceed.
        if rpm_limit >= 0 and minute_count + 1 > rpm_limit:
            return key_row, _err("RATE_LIMIT", "Rate limit exceeded for this API key (per-minute).",
                                 limit=rpm_limit, window="minute")
        if rpd_limit >= 0 and day_count + 1 > rpd_limit:
            return key_row, _err("QUOTA_EXCEEDED", "Daily request quota exceeded for this API key.",
                                 limit=rpd_limit, window="day")

        # Count this call (reads included) as usage.
        key_row["usage_minute_count"] = minute_count + 1
        key_row["usage_day_count"] = day_count + 1
        key_row["last_used_at"] = _iso(now)
        key_row["updated_at"] = _iso(now)
        _save("api_keys.json", keys)

        return key_row, None

    # -----------------------------
    # Validate inputs
    # -----------------------------
    if not isinstance(api_key, str) or not re.match(r"^wthr_key_[0-9A-Z]{3,}$", api_key):
        # Still log the call (anonymous/unknown key) as failed (cannot resolve key usage)
        started = _now()
        finished = _now()
        _append_weather_request_log(None, "failed", started, finished, "UNAUTHORIZED", "Invalid api_key format.")
        return _err("VALIDATION_ERROR", "api_key must match ^wthr_key_[0-9A-Z]{3,}$")

    if not isinstance(id, str) or not id:
        started = _now()
        finished = _now()
        # Try to log against provided key id (may not exist)
        _append_weather_request_log(api_key, "failed", started, finished, "VALIDATION_ERROR", "Missing provider config id.")
        return _err("VALIDATION_ERROR", "id is required and must be a non-empty string.")

    if status is not None and status not in ("active", "disabled"):
        started = _now()
        finished = _now()
        _append_weather_request_log(api_key, "failed", started, finished, "VALIDATION_ERROR", "Invalid status.")
        return _err("VALIDATION_ERROR", "status must be one of: active, disabled.")

    if base_url is not None and (not isinstance(base_url, str) or not base_url.strip()):
        started = _now()
        finished = _now()
        _append_weather_request_log(api_key, "failed", started, finished, "VALIDATION_ERROR", "Invalid base_url.")
        return _err("VALIDATION_ERROR", "base_url must be a non-empty string.")

    if auth_type is not None and auth_type not in ("none", "api_key"):
        started = _now()
        finished = _now()
        _append_weather_request_log(api_key, "failed", started, finished, "VALIDATION_ERROR", "Invalid auth_type.")
        return _err("VALIDATION_ERROR", "auth_type must be one of: none, api_key.")

    if priority is not None:
        if not isinstance(priority, int) or priority < 0 or priority > 1000000:
            started = _now()
            finished = _now()
            _append_weather_request_log(api_key, "failed", started, finished, "VALIDATION_ERROR", "Invalid priority.")
            return _err("VALIDATION_ERROR", "priority must be an integer between 0 and 1000000.")

    if timeout_ms is not None:
        if not isinstance(timeout_ms, int) or timeout_ms < 100 or timeout_ms > 120000:
            started = _now()
            finished = _now()
            _append_weather_request_log(api_key, "failed", started, finished, "VALIDATION_ERROR", "Invalid timeout_ms.")
            return _err("VALIDATION_ERROR", "timeout_ms must be an integer between 100 and 120000.")

    if max_retries is not None:
        if not isinstance(max_retries, int) or max_retries < 0 or max_retries > 10:
            started = _now()
            finished = _now()
            _append_weather_request_log(api_key, "failed", started, finished, "VALIDATION_ERROR", "Invalid max_retries.")
            return _err("VALIDATION_ERROR", "max_retries must be an integer between 0 and 10.")

    if api_key_ref is not None and (not isinstance(api_key_ref, str) or not api_key_ref.strip()):
        started = _now()
        finished = _now()
        _append_weather_request_log(api_key, "failed", started, finished, "VALIDATION_ERROR", "Invalid api_key_ref.")
        return _err("VALIDATION_ERROR", "api_key_ref must be a non-empty string when provided.")

    # If auth_type implies api_key_ref requirement, enforce (and also clear if switching to none).
    if auth_type == "api_key" and not api_key_ref:
        started = _now()
        finished = _now()
        _append_weather_request_log(api_key, "failed", started, finished, "VALIDATION_ERROR", "api_key_ref required.")
        return _err("VALIDATION_ERROR", "api_key_ref is required when auth_type='api_key'.")

    # -----------------------------
    # Authenticate (ambient via api_key id) + rate/quota + audit row (received)
    # -----------------------------
    started = _now()

    # Record "received" before doing any work (business rule for weather tool; here we reuse same request log collection for all calls)
    received_row = _append_weather_request_log(api_key, "received", started, None, None, None)

    key_row, key_err = _resolve_key_and_enforce_limits(api_key, started)
    if key_err:
        finished = _now()
        # transition received -> throttled/failed (allowed)
        status_val = "throttled" if key_err["error"]["code"] in ("RATE_LIMIT", "QUOTA_EXCEEDED") else "failed"
        _append_weather_request_log(api_key, status_val, started, finished, key_err["error"]["code"], key_err["error"]["message"])
        return key_err

    # -----------------------------
    # Load provider_configs and update target row
    # -----------------------------
    configs = _load("provider_configs.json")
    if not isinstance(configs, list):
        configs = []

    target = None
    for row in configs:
        if isinstance(row, dict) and row.get("id") == id:
            target = row
            break

    if not target:
        finished = _now()
        _append_weather_request_log(api_key, "failed", started, finished, "NOT_FOUND", "Provider config not found.")
        return _err("NOT_FOUND", "Provider config not found.", id=id)

    # Determine and validate requested auth mapping.
    # Datastore schema uses auth_type enum: none/api_key_header/api_key_query.
    # Tool schema exposes: none/api_key. Map api_key -> preserve existing header/query if present, else default to api_key_header.
    new_auth_type_store = None
    if auth_type is not None:
        if auth_type == "none":
            new_auth_type_store = "none"
        else:
            existing = target.get("auth_type")
            if existing in ("api_key_header", "api_key_query"):
                new_auth_type_store = existing
            else:
                new_auth_type_store = "api_key_header"

    # Validate provider/auth_type combos: in this service, all providers support none or api_key_*;
    # but "api_key" cannot be used without api_key_ref.
    if new_auth_type_store in ("api_key_header", "api_key_query"):
        ref_val = api_key_ref if api_key_ref is not None else target.get("api_key_ref")
        if not ref_val:
            finished = _now()
            _append_weather_request_log(api_key, "failed", started, finished, "VALIDATION_ERROR",
                                        "api_key_ref required for api_key auth.")
            return _err("VALIDATION_ERROR", "api_key_ref is required when auth_type='api_key'.")
    if new_auth_type_store == "none":
        # If explicitly setting to none and api_key_ref was also passed non-empty, that's allowed but inconsistent;
        # keep ref as-is unless caller explicitly sets/clears it (tool can't clear with null). We'll leave it unchanged.
        pass

    # Status transition validation (active <-> disabled)
    if status is not None and status != target.get("status"):
        cur = target.get("status")
        allowed = {"active": ["disabled"], "disabled": ["active"]}
        if cur not in allowed or status not in allowed.get(cur, []):
            finished = _now()
            _append_weather_request_log(api_key, "failed", started, finished, "INVALID_TRANSITION",
                                        f"Illegal status transition from {cur} to {status}.")
            return _err("INVALID_TRANSITION", f"Illegal status transition from {cur} to {status}.",
                        from_status=cur, to_status=status)

    # Apply changes
    changed = False
    if status is not None and status != target.get("status"):
        target["status"] = status
        changed = True
    if base_url is not None and base_url != target.get("base_url"):
        target["base_url"] = base_url
        changed = True
    if new_auth_type_store is not None and new_auth_type_store != target.get("auth_type"):
        target["auth_type"] = new_auth_type_store
        changed = True
    if api_key_ref is not None and api_key_ref != target.get("api_key_ref"):
        target["api_key_ref"] = api_key_ref
        changed = True
    if priority is not None and priority != target.get("priority"):
        target["priority"] = priority
        changed = True
    if timeout_ms is not None and timeout_ms != target.get("timeout_ms"):
        target["timeout_ms"] = timeout_ms
        changed = True
    if max_retries is not None and max_retries != target.get("max_retries"):
        target["max_retries"] = max_retries
        changed = True

    if not changed:
        # Idempotent: still a real call with effects already applied; return current row.
        finished = _now()
        _append_weather_request_log(api_key, "succeeded", started, finished, None, None)
        return {
            "provider_config": target,
            "idempotent": True,
        }

    # Update timestamps
    now = _now()
    if "created_at" not in target or not target.get("created_at"):
        target["created_at"] = _iso(now)
    target["updated_at"] = _iso(now)

    # Persist
    _save("provider_configs.json", configs)

    finished = _now()
    _append_weather_request_log(api_key, "succeeded", started, finished, None, None)

    return {
        "provider_config": target
    }
